local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[403203]=b({e[21034],403203,9,70,191,"「リサリサが羊を数えてあげるね。羊が1匹……2匹……さん……ふぁ～」",200032,2,"deco/character/ailisha_SY",false,false,1,false,false,false,false,"1",false,false,false,"80,-130,1",1807,1006,382,808,468,2243,2378,808,696,2243,1261,false,false,false,false,false,false,false,false,false,false,false,false,"ailisha_sy"},h)g[403204]=b({e[9020],403204,6,88,192,"「オオカミさーん！　魚の丸揚げの甘酢あんかけを手土産に持ってきたよ！　オオカミさんのお腹が空いたら、リサリサとぽややんを食べないでお魚さんを食べてね！」",200032,2,"deco/character/403204","-85,0,1","-110,0,1",false,false,false,false,false,false,false,false,false,false,false,false,1852,876,361,1086,671,2090,2770,1086,671,2090,1146,1,5330,7065,2650,4950,6667,6667,6667,6667,6667,false,6667,"ailisha_cj",false,0},h)g[403205]=b({e[21034],403205,3,24,193,"「ガ、ガオー！　リサリサ、大勝利～……って、あわわわ！　オオカミさん避けてー！　むむ、このチェーンソーやっぱり重いよ～。……そうだ、明日からリサリサもオオカミさんと一緒にトレーニングしよっかな！　えへへ。」",200032,2,"deco/character/ailisha_WS",false,false,1,false,false,false,false,false,false,false,false,"100,-220,1",1965,870,384,802,322,2546,2790,802,561,2546,1261,false,false,false,false,false,false,false,false,false,false,false,false,"ailisha_ws"},h)g[403206]=b({e[23034],403206,16,44,194,"「うわあ～！　サーキットって、いいね！　牧場みたいな雰囲気だー！　どんな雰囲気かって？　むむむ……なんかこう、風をうけて、前へ自由に進める感じ、かなぁ？　えへへ。オオカミさん、リサリサともう一周走ろ？」",200032,2,"deco/character/ailisha_SC",false,false,1,false,false,false,false,"1",false,false,false,"240,-130,1",false,"-200,0,1",1730,918,384,1230,668,2154,2283,1230,668,2154,1202,1,3786,5000,1397,2411,8000,13333,13833,14400,12000,8000,8000,"ailisha_sc"},h)g[403207]=b({e[17057],403207,4,98,195,"「わ～っ、今日の雪、ふわふわ。踏んでみると、まるで刈った羊さんの毛の山みたい！\nオオカミさん、一緒に雪だるま作ろ？ リサリサは、かわいい雪の羊さんを作るね！\nオオカミさんは、かっこよくて、いつもリサリサを守ってくれる、優しいオオカミさんを作って！ ぽややんは、指導役をお願い！\nリサリサと、オオカミさん、それにぽややんで、今日は世界でいっちばん幸せなクリスマス牧場を作っちゃおう！」",200032,2,"deco/character/ailisha_sd",false,false,false,false,false,false,false,"","ailisha_sd"},h)g[403301]=b({e[17057],403301,false,99,196,false,200033,false,"deco/character/siqiqiansuili",302002,60,false,false,false,false,124,"0.949999988079071","siqiqiansuili"},h)g[403302]=b({e[12057],403302,1,4,197,"「君の影響で、こうしてゆったりとした午後を過ごしているけれど……良いんだか悪いんだか。\nどうやら私も『堕ちた』ようね、ふふっ。」",200033,1,"deco/character/siqiqiansuili_0",302002,60,1,"siqiqiansuili_0"},h)g[403303]=b({e[17057],403303,11,57,198,"「早くしないと置いてくわよ！　……二人きりのお出かけなのに、仕事のことを優先しちゃうなんて、悪いとは思ってるわ。でもね、あれは結構な特ダネなのよ！　終わったらどこにでも付き合うから、今は許して！　ね？」",200033,2,"deco/character/siqiqiansuili_YY",false,false,1,1,false,false,false,"1","siqiqiansuili_yy"},h)g[403304]=b({e[17045],403304,2,14,199,"「さ、こっちに座って。一緒に飲みながら、日光浴を楽しみましょ。そうだ、日焼け止めを塗ってあげるわ。私の塗りの技術、しっかり肌で感じてね。後でじっくりとインタビューさせてもらうから。」",200033,2,"deco/character/siqiqiansuili_YZ",false,false,false,false,false,false,false,"1",1,3858,5000,1655,3999,13333,6666,6666,13366,15000,8000,13333,"siqiqiansuili_xr"},h)g[403305]=b({e[17057],403305,13,46,200,"「噂の真偽に対する探求心は、ジャーナリストの性のようなものね。\nこの『みかんの湯』のうるおい効果がどれほどのものか……ふふっ、一緒に検証しましょうか。」",200033,2,"deco/character/siqiqiansuili_wq",false,false,1,1,false,false,false,"1","siqiqiansuili_wq"},h)g[403401]=b({e[17034],403401,false,100,201,false,200034,false,"deco/character/gongyongxiao",302002,60,false,false,false,false,245,"1",1851,977,429,1599,931,1164,2139,1599,931,1164,1021},h)g[403402]=b({e[12034],403402,1,4,202,false,200034,1,"deco/character/gongyongxiao_0",302002,60,1,1874,942,454,1380,928,1637,2237,1380,928,1637,1001},h)g[403403]=b({e[9034],403403,999,101,203,false,200034,3,"deco/character/gongyongxiao_flower",1867,954,419,1324,884,1361,2090,1324,884,1361,1040},h)g[403404]=b({e[9034],403404,998,102,204,false,200034,3,"deco/character/gongyongxiao_bunny",1886,1011,408,912,399,2108,2628,912,714,2108,1261},h)g[403501]=b({e[17034],403501,false,103,205,false,200035,false,"deco/character/yuancunhe",302002,60,1,false,false,false,286,"1",1849,1002,436,1592,971,1081,2078,1592,971,1081,1009},h)g[403502]=b({e[11034],403502,1,4,206,false,200035,1,"deco/character/yuancunhe_0"